1	import { BadRequestException, ConflictException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	import { normalizarDominio, validarFormatoDominio, isDominioReservado } from '../common/dominio.util';
4	import { CategoriasService } from '../categorias/categorias.service';
5	import { ProdutosService } from '../produtos/produtos.service';
6	import { PedidosService } from '../pedidos/pedidos.service';
7	import { GeocodingService } from '../motoboy/geocoding.service';
8	import { MotoboyService } from '../motoboy/motoboy.service';
9	import { EstoqueService } from '../estoque/estoque.service';
10	import { CombosService } from '../combos/combos.service';
11	import { PlanosService } from '../planos/planos.service';
12	import { RedisService } from '../redis/redis.service';
13	
14	const TTL_MINHA_EMPRESA = 15;
15	
16	@Injectable()
17	export class RestauranteService {
18	  constructor(
19	    private supabase: SupabaseService,
20	    private categorias: CategoriasService,
21	    private produtos: ProdutosService,
22	    private pedidos: PedidosService,
23	    private geocoding: GeocodingService,
24	    private motoboyService: MotoboyService,
25	    private estoque: EstoqueService,
26	    private combosService: CombosService,
27	    private planos: PlanosService,
28	    private redis: RedisService,
29	  ) {}
30	
31	  // Cacheada porque o header do painel (menu lateral) monta 3 hooks que bateriam
32	  // nessa rota em paralelo — cache-aside curto evita repetir as 3 queries a cada
33	  // navegação entre páginas de /restaurante/*. Mesmo padrão do catálogo público
34	  // (ver CatalogoController): sem invalidação manual, defasagem curta é aceitável.
35	  async minhaEmpresa(userId: string) {
36	    const cacheKey = `restaurante:minha-empresa:${userId}`;
37	    const cached = await this.redis.getJSON<any>(cacheKey);
38	    if (cached) return cached;
39	
40	    const resultado = await this.buscarMinhaEmpresa(userId);
41	    await this.redis.setJSON(cacheKey, resultado, TTL_MINHA_EMPRESA);
42	    return resultado;
43	  }
44	
45	  private async buscarMinhaEmpresa(userId: string) {
46	    const { data, error } = await this.supabase.client
47	      .from('restaurants')
48	      .select('id, name, address, state, city, neighborhood, cep, lat, lng, lat_ajustado_manualmente, logo_url, slug, custom_domain, custom_domain_status, custom_domain_motivo_recusa, business_hours, payment_config, comissao_pct, type_id, modulo_delivery, modulo_salao, auto_atendimento_habilitado, created_at')
49	      .eq('user_id', userId)
50	      .maybeSingle();
51	
52	    if (error) throw error;
53	    if (!data) throw new NotFoundException('Nenhum restaurante vinculado');
54	
55	    const { data: tipoRestaurante } = await this.supabase.client
56	      .from('establishment_types')
57	      .select('id')
58	      .eq('name', 'Restaurante')
59	      .maybeSingle();
60	
61	    const { data: pedidosData } = await this.supabase.client
62	      .from('orders')
63	      .select('id, total, status')
64	      .eq('restaurant_id', data.id);
65	
66	    const entregues = (pedidosData ?? []).filter((p) => p.status === 'delivered');
67	    const pendentes = (pedidosData ?? []).filter((p) =>
68	      ['pending', 'confirmed', 'ready', 'out_for_delivery'].includes(p.status),
69	    );
70	    const faturamento = entregues.reduce((acc, p) => acc + (p.total ?? 0), 0);
71	
72	    return {
73	      empresa: { ...data, tipo_restaurante: data.type_id === tipoRestaurante?.id },
74	      metricas: {
75	        total_pedidos: pedidosData?.length ?? 0,
76	        pedidos_pendentes: pendentes.length,
77	        pedidos_entregues: entregues.length,
78	        faturamento,
79	      },
80	    };
81	  }
82	
83	  async meusPedidos(restaurantId: number, filtros: { status?: string; limite?: number }) {
84	    return this.pedidos.listar({
85	      empresa_id: restaurantId,
86	      status: filtros.status,
87	      limite: filtros.limite ?? 50,
88	    });
89	  }
90	
91	  async cancelarPedidoAdmin(restaurantId: number, pedidoId: number, motivo: string) {
92	    if (!motivo?.trim()) throw new BadRequestException('Motivo do cancelamento é obrigatório');
93	
94	    const { data: pedido, error } = await this.supabase.client
95	      .from('orders')
96	      .select('id, status')
97	      .eq('id', pedidoId)
98	      .eq('restaurant_id', restaurantId)
99	      .maybeSingle();
100	
101	    if (error) throw error;
102	    if (!pedido) throw new NotFoundException('Pedido não encontrado neste restaurante');
103	    if (pedido.status === 'canceled') throw new BadRequestException('Pedido já está cancelado');
104	
105	    const { data, error: errUpd } = await this.supabase.client
106	      .from('orders')
107	      .update({ status: 'canceled', cancel_reason: motivo.trim(), updated_at: new Date().toISOString() })
108	      .eq('id', pedidoId)
109	      .eq('restaurant_id', restaurantId)
110	      .select('id, status, cancel_reason, total, updated_at')
111	      .single();
112	
113	    if (errUpd) throw errUpd;
114	
115	    await this.estoque.restaurarItensDoPedido(pedidoId);
116	
117	    return data;
118	  }
119	
120	  async atualizarStatusPedido(pedidoId: number, restaurantId: number, status: string) {
121	    const { data: pedido } = await this.supabase.client
122	      .from('orders')
123	      .select('id')
124	      .eq('id', pedidoId)
125	      .eq('restaurant_id', restaurantId)
126	      .maybeSingle();
127	
128	    if (!pedido) throw new NotFoundException('Pedido não encontrado neste restaurante');
129	
130	    return this.pedidos.atualizarStatus(pedidoId, status as any);
131	  }
132	
133	  // Painel de controle de entregas: tudo que está "em voo" agora (pronto aguardando
134	  // atribuição, indo buscar, ou já saiu pra entrega), com dados de quem está entregando.
135	  async listarEntregas(restaurantId: number) {
136	    const { data, error } = await this.supabase.client
137	      .from('orders')
138	      .select(
139	        'id, status, total, payment_method, motoboy_id, entrega_propria, motoboy_lat, motoboy_lng, motoboy_location_at, created_at, updated_at, customer_id',
140	      )
141	      .eq('restaurant_id', restaurantId)
142	      .in('status', ['ready', 'motoboy_collecting', 'out_for_delivery'])
143	      .order('created_at', { ascending: true });
144	    if (error) throw error;
145	
146	    const motoboyIds = [...new Set((data ?? []).map((o) => o.motoboy_id).filter(Boolean))];
147	    const customerIds = [...new Set((data ?? []).map((o) => o.customer_id).filter(Boolean))];
148	
149	    const [{ data: motoboys }, { data: customers }] = await Promise.all([
150	      motoboyIds.length
151	        ? this.supabase.client.from('motoboys').select('id, name, phone').in('id', motoboyIds)
152	        : Promise.resolve({ data: [] as any[] }),
153	      customerIds.length
154	        ? this.supabase.client.from('customers').select('id, name, address_json').in('id', customerIds)
155	        : Promise.resolve({ data: [] as any[] }),
156	    ]);
157	    const motoboyMap = Object.fromEntries((motoboys ?? []).map((m: any) => [m.id, m]));
158	    const customerMap = Object.fromEntries((customers ?? []).map((c: any) => [c.id, c]));
159	
160	    const entregas = (data ?? []).map((o) => ({
161	      ...o,
162	      motoboy: o.motoboy_id ? motoboyMap[o.motoboy_id] ?? null : null,
163	      cliente: o.customer_id ? customerMap[o.customer_id] ?? null : null,
164	    }));
165	    return { entregas };
