300	  async getComboDetalhe(comboId: number, restaurantId: number) {
301	    const { data: combo } = await this.supabase.client
302	      .from('combos').select('*').eq('id', comboId).eq('restaurant_id', restaurantId).maybeSingle();
303	    if (!combo) throw new NotFoundException('Combo não encontrado');
304	
305	    const { data: items } = await this.supabase.client
306	      .from('combo_items')
307	      .select('id, quantity, product_id, preco_no_combo, products(id, name, price, image_url)')
308	      .eq('combo_id', comboId);
309	
310	    return { ...combo, items: items ?? [] };
311	  }
312	
313	  // Preço (R$) e Preço promo (R$) do combo NÃO vêm do client (Zero Trust) — são
314	  // calculados aqui a partir do preço real de cada produto (tabela `products`) e do
315	  // `preco_no_combo` que o dono escolheu pra cada item (o que ele decide cobrar por
316	  // aquele produto especificamente dentro do combo).
317	  private async calcularPrecosCombo(restaurantId: number, items: { product_id: number; quantity: number; preco_no_combo: number }[]) {
318	    if (!items?.length) throw new BadRequestException('Adicione pelo menos 1 produto ao combo');
319	
320	    const prodIds = items.map((i) => i.product_id);
321	    const { data: produtos } = await this.supabase.client
322	      .from('products').select('id, price').eq('restaurant_id', restaurantId).in('id', prodIds);
323	    const prodMap = Object.fromEntries((produtos ?? []).map((p) => [p.id, p]));
324	
325	    let precoTotal = 0;
326	    let precoPromoTotal = 0;
327	    for (const item of items) {
328	      const prod = prodMap[item.product_id];
329	      if (!prod) throw new BadRequestException(`Produto ${item.product_id} não encontrado`);
330	      if (item.preco_no_combo == null || item.preco_no_combo < 0) {
331	        throw new BadRequestException('Informe o valor cobrado no combo pra cada produto');
332	      }
333	      precoTotal += prod.price * item.quantity;
334	      precoPromoTotal += item.preco_no_combo * item.quantity;
335	    }
336	
337	    return {
338	      price: parseFloat(precoTotal.toFixed(2)),
339	      preco_promo: parseFloat(precoPromoTotal.toFixed(2)),
340	    };
341	  }
