429	  async listarClientes(restaurantId: number, filtros: { busca?: string; limite?: number }) {
430	    // Busca IDs dos clientes vinculados a este restaurante
431	    const { data: crRows, error: crErr } = await this.supabase.client
432	      .from('customer_restaurants')
433	      .select('customer_id')
434	      .eq('restaurant_id', restaurantId);
435	
436	    if (crErr) throw crErr;
437	    const customerIds = (crRows ?? []).map((r) => r.customer_id);
438	    if (customerIds.length === 0) return { clientes: [], total: 0 };
439	
440	    // Busca dados dos clientes com filtro opcional
441	    let q = this.supabase.client
442	      .from('customers')
443	      .select('id, name, email, phone_e164, notes, user_id, created_at')
444	      .in('id', customerIds)
445	      .order('name');
446	
447	    if (filtros.busca) {
448	      q = q.or(`name.ilike.%${filtros.busca}%,email.ilike.%${filtros.busca}%,phone_e164.ilike.%${filtros.busca}%`);
449	    }
450	    if (filtros.limite) q = q.limit(filtros.limite);
451	
452	    const { data: clientes, error: cErr } = await q;
453	    if (cErr) throw cErr;
454	
455	    if (!clientes?.length) return { clientes: [], total: 0 };
456	
457	    // Busca estatísticas de pedidos por cliente neste restaurante
458	    const ids = clientes.map((c) => c.id);
459	    const { data: pedidos } = await this.supabase.client
460	      .from('orders')
461	      .select('customer_id, total, created_at')
462	      .eq('restaurant_id', restaurantId)
463	      .in('customer_id', ids)
464	      .neq('status', 'canceled');
465	
466	    const statsMap: Record<number, { count: number; total: number; ultimo: string | null }> = {};
467	    for (const p of pedidos ?? []) {
468	      if (!statsMap[p.customer_id]) statsMap[p.customer_id] = { count: 0, total: 0, ultimo: null };
469	      statsMap[p.customer_id].count++;
470	      statsMap[p.customer_id].total += parseFloat(p.total);
471	      if (!statsMap[p.customer_id].ultimo || p.created_at > (statsMap[p.customer_id].ultimo as string)) {
472	        statsMap[p.customer_id].ultimo = p.created_at;
473	      }
474	    }
475	
476	    const result = clientes.map((c) => ({
477	      ...c,
478	      pedidos_count: statsMap[c.id]?.count ?? 0,
479	      total_gasto: statsMap[c.id]?.total ?? 0,
480	      ultimo_pedido: statsMap[c.id]?.ultimo ?? null,
481	    }));
482	
483	    return { clientes: result, total: result.length };
484	  }
