538	  async updateEmpresa(
539	    restaurantId: number,
540	    body: { name?: string; address?: string; state?: string; city?: string; neighborhood?: string; cep?: string; logo_url?: string; slug?: string },
541	  ) {
542	    const campos: Record<string, any> = { updated_at: new Date().toISOString() };
543	    if (body.name !== undefined) campos.name = body.name;
544	    if (body.address !== undefined) campos.address = body.address;
545	    if (body.state !== undefined) campos.state = body.state;
546	    if (body.city !== undefined) campos.city = body.city;
547	    if (body.neighborhood !== undefined) campos.neighborhood = body.neighborhood;
548	    if (body.cep !== undefined) campos.cep = body.cep ? body.cep.replace(/\D/g, '') : null;
549	    if (body.logo_url !== undefined) campos.logo_url = body.logo_url;
550	    if (body.slug !== undefined) {
551	      const slug = body.slug.trim().toLowerCase();
552	      if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(slug) || slug.length < 3 || slug.length > 60) {
553	        throw new BadRequestException('Link inválido. Use só letras minúsculas, números e hífen (mín. 3 caracteres), sem começar/terminar com hífen.');
554	      }
555	      campos.slug = slug;
556	    }
557	
558	    const { data, error } = await this.supabase.client
559	      .from('restaurants')
560	      .update(campos)
561	      .eq('id', restaurantId)
562	      .select('id, name, address, state, city, neighborhood, cep, logo_url, slug, lat_ajustado_manualmente')
563	      .maybeSingle();
564	
565	    if (error) {
566	      if ((error as any).code === '23505') {
567	        throw new ConflictException('Esse link já está em uso por outro estabelecimento.');
568	      }
569	      throw error;
570	    }
571	
572	    // Geocodifica em background (best-effort) sempre que algum campo de endereço mudou —
573	    // usa o endereço completo (rua + bairro + cidade + estado + cep), não só o campo livre
574	    // "address" sozinho, que sem cidade/estado o Nominatim geocodificava impreciso/errado
575	    // (ex: rua comum sem contexto de cidade cai em outro município, filtro por raio nunca
576	    // encontrava o próprio restaurante). Nunca falha o save do endereço por causa disso.
577	    // Pula se o dono já ajustou o pino manualmente no mapa — geocode automático não pode
578	    // sobrescrever silenciosamente uma localização que ele calibrou de propósito.
579	    if (
580	      !data?.lat_ajustado_manualmente &&
581	      (body.address !== undefined || body.state !== undefined || body.city !== undefined || body.neighborhood !== undefined || body.cep !== undefined)
582	    ) {
583	      this.geocodificarEndereco(restaurantId, {
584	        address: data?.address ?? null,
585	        neighborhood: data?.neighborhood ?? null,
586	        city: data?.city ?? null,
587	        state: data?.state ?? null,
588	        cep: data?.cep ?? null,
589	      }).catch(() => {});
590	    }
591	
592	    return data;
593	  }
594	
595	  // Pino arrastado manualmente no mapa (ver EnderecoCard) — sobrescreve o geocode
596	  // automático do Nominatim, que erra rooftop-level em endereço brasileiro fora de
597	  // área bem mapeada. Fica marcado como ajuste manual: futuras edições de endereço
598	  // não voltam a sobrescrever essa coordenada calibrada (ver updateEmpresa acima).
599	  async atualizarLocalizacaoManual(restaurantId: number, lat: number, lng: number) {
600	    if (typeof lat !== 'number' || typeof lng !== 'number' || Number.isNaN(lat) || Number.isNaN(lng)) {
601	      throw new BadRequestException('Latitude/longitude inválidas.');
602	    }
603	    if (lat < -90 || lat > 90 || lng < -180 || lng > 180) {
604	      throw new BadRequestException('Latitude/longitude fora do intervalo válido.');
605	    }
606	
607	    const { data, error } = await this.supabase.client
608	      .from('restaurants')
609	      .update({
610	        lat,
611	        lng,
612	        lat_ajustado_manualmente: true,
613	        geocode_falhou: false,
614	        geocoded_at: new Date().toISOString(),
615	        updated_at: new Date().toISOString(),
616	      })
617	      .eq('id', restaurantId)
618	      .select('id, lat, lng, lat_ajustado_manualmente')
619	      .maybeSingle();
620	
621	    if (error) throw error;
622	    return data;
623	  }
