883	  // KDS por setor (módulo Salão): tela genérica reaproveitável por impressora/setor
884	  // (cozinha, bar, salgados...) — lista PLANA de itens (não agrupa por mesa/comanda,
885	  // cada item tem sua própria ação de preparo/impressão), ordenada por chegada.
886	  async getKdsSetor(restaurantId: number, impressoraId: number) {
887	    // Itens "pronto" de hoje inteiro também entram — sem isso, um clique errado em
888	    // "Entregue"/"Pronto" faz o item sumir da tela sem chance de desfazer. A tela
889	    // (Cozinha/Produção) que decide mostrar só os últimos N com opção de expandir.
890	    const inicioDoDia = new Date();
891	    inicioDoDia.setHours(0, 0, 0, 0);
892	    const limiteProntos = inicioDoDia.toISOString();
893	    const { data: itens, error } = await this.supabase.client
894	      .from('order_items')
895	      .select('id, quantity, unit_price, observacao, product_id, status, enviado_em, preparando_em, pronto_em, entregue_garcom, garcom_nao_entregou, garcom_indo_buscar, ordem_fila, order_id, products(name), orders(id, restaurant_id, mesa_id, cliente_mesa_nome, garcom_id, customer_id, status, numero_comanda, is_venda_balcao, aberto_por_nome, motoboy_lat, motoboy_lng, delivery_occurrence, mesas(numero, nome), garcons(nome))')
896	      .eq('impressora_id', impressoraId)
897	      .or(`status.in.(enviado,preparando),and(status.eq.pronto,pronto_em.gte.${limiteProntos})`)
898	      .order('ordem_fila', { ascending: true, nullsFirst: false })
899	      .order('enviado_em', { ascending: true });
900	    if (error) throw error;
901	
902	    const itensValidos = (itens as any[]).filter((i) => i.orders?.restaurant_id === restaurantId);
903	
904	    // Um item roteado pra uma impressora/setor pode vir tanto de comanda do salão
905	    // (mesa_id/garcom_id preenchidos) quanto de pedido de delivery (produto com a
906	    // mesma impressora configurada) — resolve nome do cliente de delivery à parte
907	    // pra tela poder filtrar e exibir por canal.
908	    const customerIds = [...new Set(itensValidos.map((i) => i.orders?.customer_id).filter(Boolean))];
909	    const { data: customers } = customerIds.length
910	      ? await this.supabase.client.from('customers').select('id, name').in('id', customerIds)
911	      : { data: [] as any[] };
912	    const customerMap = Object.fromEntries((customers ?? []).map((c: any) => [c.id, c.name]));
913	
914	    return {
915	      itens: itensValidos.map((i) => {
916	        const ehSalao = !!(i.orders?.mesa_id || i.orders?.garcom_id || i.orders?.cliente_mesa_nome);
917	        const ehAutoAtendimento = i.orders?.aberto_por_nome === 'Auto Atendimento';
918	        return {
919	          id: i.id,
920	          order_id: i.order_id,
921	          product_name: i.products?.name,
922	          quantity: i.quantity,
923	          observacao: i.observacao,
924	          status: i.status,
925	          enviado_em: i.enviado_em,
926	          preparando_em: i.preparando_em,
927	          pronto_em: i.pronto_em,
928	          entregue_garcom: i.entregue_garcom ?? false,
929	          garcom_nao_entregou: i.garcom_nao_entregou ?? false,
930	          garcom_indo_buscar: i.garcom_indo_buscar ?? false,
931	          tipo: ehSalao ? 'salao' : 'delivery',
932	          is_auto_atendimento: ehAutoAtendimento,
933	          mesa: i.orders?.mesas ? `Mesa ${i.orders.mesas.numero}${i.orders.mesas.nome ? ' - ' + i.orders.mesas.nome : ''}` : null,
934	          mesa_numero: i.orders?.mesas?.numero ?? null,
935	          numero_comanda: i.orders?.numero_comanda ?? null,
936	          cliente: i.orders?.cliente_mesa_nome ?? (i.orders?.customer_id ? customerMap[i.orders.customer_id] ?? null : null),
937	          garcom: i.orders?.garcons?.nome
938	            ?? (ehAutoAtendimento ? 'Auto Atendimento' : i.orders?.is_venda_balcao ? 'Balcão' : (ehSalao ? 'Sem Garçom - Venda Direta' : null)),
939	          venda_balcao: i.orders?.is_venda_balcao ?? false,
940	          // Status de entrega do pedido (delivery) — usado no Bar pra alerta de motoboy
941	          // (em trânsito/entregue/ocorrência) e botão de localizar no mapa.
942	          pedido_status: i.orders?.status ?? null,
943	          motoboy_lat: i.orders?.motoboy_lat ?? null,
944	          motoboy_lng: i.orders?.motoboy_lng ?? null,
945	          delivery_occurrence: i.orders?.delivery_occurrence ?? null,
946	        };
947	      }),
948	    };
949	  }
