1001	    if (item.status === 'pronto') {
1002	      const { error } = await this.supabase.client
1003	        .from('order_items')
1004	        .update({ status: 'preparando', pronto_em: null })
1005	        .eq('id', itemId);
1006	      if (error) throw error;
