1052	  // Adiantar/atrasar item na fila "Aguardando Preparo" — troca de posição com o vizinho
1053	  // (cima/baixo). Resequencia ordem_fila de TODOS os itens "enviado" do setor pra manter
1054	  // consistência: sem isso, itens ainda sem ordem_fila (null) ficariam intercalados de
1055	  // forma imprevisível com os já reordenados.
1056	  async moverPosicaoItem(itemId: number, restaurantId: number, direcao: 'cima' | 'baixo') {
1057	    const { data: item } = await this.supabase.client
1058	      .from('order_items')
1059	      .select('id, status, impressora_id, order_id, orders(restaurant_id)')
1060	      .eq('id', itemId)
1061	      .maybeSingle();
1062	
1063	    if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
1064	      throw new NotFoundException('Item não encontrado');
1065	    }
1066	    if (item.status !== 'enviado') {
1067	      throw new BadRequestException('Só é possível reordenar um item enquanto está Aguardando Preparo');
1068	    }
1069	
1070	    const { data: fila, error } = await this.supabase.client
1071	      .from('order_items')
1072	      .select('id, ordem_fila, enviado_em')
1073	      .eq('impressora_id', item.impressora_id)
1074	      .eq('status', 'enviado')
1075	      .order('ordem_fila', { ascending: true, nullsFirst: false })
1076	      .order('enviado_em', { ascending: true });
1077	    if (error) throw error;
1078	
1079	    const lista = fila as any[];
1080	    const idx = lista.findIndex((i) => i.id === itemId);
1081	    const swapIdx = direcao === 'cima' ? idx - 1 : idx + 1;
1082	    if (idx === -1 || swapIdx < 0 || swapIdx >= lista.length) {
1083	      throw new BadRequestException('Item já está na ponta da fila');
1084	    }
1085	
1086	    [lista[idx], lista[swapIdx]] = [lista[swapIdx], lista[idx]];
1087	
