  async updateEmpresa(
    restaurantId: number,
    body: { name?: string; address?: string; state?: string; city?: string; neighborhood?: string; cep?: string; logo_url?: string; slug?: string },
  ) {
    const campos: Record<string, any> = { updated_at: new Date().toISOString() };
    if (body.name !== undefined) campos.name = body.name;
    if (body.address !== undefined) campos.address = body.address;
    if (body.state !== undefined) campos.state = body.state;
    if (body.city !== undefined) campos.city = body.city;
    if (body.neighborhood !== undefined) campos.neighborhood = body.neighborhood;
    if (body.cep !== undefined) campos.cep = body.cep ? body.cep.replace(/\D/g, '') : null;
    if (body.logo_url !== undefined) campos.logo_url = body.logo_url;
    if (body.slug !== undefined) {
      const slug = body.slug.trim().toLowerCase();
      if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(slug) || slug.length < 3 || slug.length > 60) {
        throw new BadRequestException('Link inválido. Use só letras minúsculas, números e hífen (mín. 3 caracteres), sem começar/terminar com hífen.');
      }
      campos.slug = slug;
    }

    const { data, error } = await this.supabase.client
      .from('restaurants')
      .update(campos)
      .eq('id', restaurantId)
      .select('id, name, address, state, city, neighborhood, cep, logo_url, slug, lat_ajustado_manualmente')
      .maybeSingle();

    if (error) {
      if ((error as any).code === '23505') {
        throw new ConflictException('Esse link já está em uso por outro estabelecimento.');
      }
      throw error;
    }

    // Geocodifica em background (best-effort) sempre que algum campo de endereço mudou —
    // usa o endereço completo (rua + bairro + cidade + estado + cep), não só o campo livre
    // "address" sozinho, que sem cidade/estado o Nominatim geocodificava impreciso/errado
    // (ex: rua comum sem contexto de cidade cai em outro município, filtro por raio nunca
    // encontrava o próprio restaurante). Nunca falha o save do endereço por causa disso.
    // Pula se o dono já ajustou o pino manualmente no mapa — geocode automático não pode
    // sobrescrever silenciosamente uma localização que ele calibrou de propósito.
    if (
      !data?.lat_ajustado_manualmente &&
      (body.address !== undefined || body.state !== undefined || body.city !== undefined || body.neighborhood !== undefined || body.cep !== undefined)
    ) {
      this.geocodificarEndereco(restaurantId, {
        address: data?.address ?? null,
        neighborhood: data?.neighborhood ?? null,
        city: data?.city ?? null,
        state: data?.state ?? null,
        cep: data?.cep ?? null,
      }).catch(() => {});
    }

    return data;
  }

  // Pino arrastado manualmente no mapa (ver EnderecoCard) — sobrescreve o geocode
  // automático do Nominatim, que erra rooftop-level em endereço brasileiro fora de
  // área bem mapeada. Fica marcado como ajuste manual: futuras edições de endereço
  // não voltam a sobrescrever essa coordenada calibrada (ver updateEmpresa acima).
  async atualizarLocalizacaoManual(restaurantId: number, lat: number, lng: number) {
    if (typeof lat !== 'number' || typeof lng !== 'number' || Number.isNaN(lat) || Number.isNaN(lng)) {
      throw new BadRequestException('Latitude/longitude inválidas.');
    }
    if (lat < -90 || lat > 90 || lng < -180 || lng > 180) {
      throw new BadRequestException('Latitude/longitude fora do intervalo válido.');
    }

    const { data, error } = await this.supabase.client
      .from('restaurants')
      .update({
        lat,
        lng,
        lat_ajustado_manualmente: true,
        geocode_falhou: false,
        geocoded_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .eq('id', restaurantId)
      .select('id, lat, lng, lat_ajustado_manualmente')
      .maybeSingle();

    if (error) throw error;
    return data;
  }

  async atualizarDominio(restaurantId: number, customDomain: string | null | undefined) {
    let valor: string | null = null;

    if (customDomain != null && customDomain.trim() !== '') {
      valor = normalizarDominio(customDomain);
      if (!validarFormatoDominio(valor)) {
        throw new BadRequestException('Domínio inválido. Use o formato "seusite.com", sem http:// ou barras.');
      }
      if (isDominioReservado(valor)) {
        throw new BadRequestException('Esse domínio é reservado da plataforma e não pode ser usado.');
      }
    }

    const { data, error } = await this.supabase.client
      .from('restaurants')
      .update({ custom_domain: valor, updated_at: new Date().toISOString() })
      .eq('id', restaurantId)
      .select('id, custom_domain')
      .maybeSingle();

    if (error) {
      if ((error as any).code === '23505') {
        throw new ConflictException('Este domínio já está em uso por outro estabelecimento.');
      }
      throw error;
    }

    return data;
  }

  async solicitarRevisaoDominio(restaurantId: number) {
    const { data: atual } = await this.supabase.client
      .from('restaurants')
      .select('custom_domain')
      .eq('id', restaurantId)
      .maybeSingle();

    if (!atual?.custom_domain) {
      throw new BadRequestException('Salve um domínio antes de enviar a solicitação.');
    }

    const { data, error } = await this.supabase.client
      .from('restaurants')
      .update({
        custom_domain_status: 'pendente',
        custom_domain_solicitado_em: new Date().toISOString(),
        custom_domain_motivo_recusa: null,
        updated_at: new Date().toISOString(),
      })
      .eq('id', restaurantId)
      .select('id, custom_domain, custom_domain_status')
      .maybeSingle();

    if (error) throw error;
    return data;
  }

  private async geocodificarEndereco(
    restaurantId: number,
    partes: { address: string | null; neighborhood: string | null; city: string | null; state: string | null; cep: string | null },
  ) {
    const texto = [partes.address, partes.neighborhood, partes.city, partes.state, partes.cep].filter(Boolean).join(', ');
    const coords = await this.geocoding.geocodeEndereco(texto);
    await this.supabase.client
      .from('restaurants')
      .update({
        lat: coords?.lat ?? null,
        lng: coords?.lng ?? null,
        geocoded_at: new Date().toISOString(),
        geocode_falhou: !coords,
      })
      .eq('id', restaurantId);
  }

