  async renovarTokenCozinha(restaurantId: number) {
    const novoToken = crypto.randomUUID();
    const { error } = await this.supabase.client
      .from('restaurants')
      .update({ cozinha_token: novoToken })
      .eq('id', restaurantId);
    if (error) throw error;
