1	import React, { useState, useEffect } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import Button from '../../components/ui/Button';
4	import Icon from '../../components/AppIcon';
5	import BusinessInformationForm from './components/BusinessInformationForm';
6	import ContactDetailsForm from './components/ContactDetailsForm';
7	import OperatingHoursForm from './components/OperatingHoursForm';
8	import BrandingForm from './components/BrandingForm';
9	import PlanSelectionForm from './components/PlanSelectionForm';
10	import ProgressSidebar from './components/ProgressSidebar';
11	import PagamentoFaturaModal from '../../components/restaurante/PagamentoFaturaModal';
12	import { registrarRestauranteInicial, finalizarCadastroRestaurante, getTiposEstabelecimento, getPlanosDisponiveisCadastro } from '../../services/restauranteService';
13	import { useAuth } from '../../contexts/AuthContext';
14	
15	const RestaurantRegistrationSetup = () => {
16	  const navigate = useNavigate();
17	  const { isAuthenticated } = useAuth();
18	  const [currentStep, setCurrentStep] = useState('plano');
19	  const [completedSteps, setCompletedSteps] = useState([]);
20	  const [loading, setLoading] = useState(false);
21	  const [errors, setErrors] = useState({});
22	  const [tiposEstabelecimento, setTiposEstabelecimento] = useState([]);
23	  const [planos, setPlanos] = useState([]);
24	  const [loadingPlanos, setLoadingPlanos] = useState(true);
25	  const [confirmandoPlano, setConfirmandoPlano] = useState(false);
26	  const [faturaPendente, setFaturaPendente] = useState(null);
27	  const [formData, setFormData] = useState({
28	    // Plano
29	    planoId: '',
30	
31	    // Business Information
32	    restaurantName: '',
33	    establishmentTypeId: '',
34	    cuisineType: '',
35	    description: '',
36	    cnpj: '',
37	    deliveryFee: '',
38	    deliveryTime: '',
39	    minimumOrder: '',
40	    deliveryRadius: '',
41	    
42	    // Contact Details
43	    whatsapp: '',
44	    email: '',
45	    cep: '',
46	    address: '',
47	    number: '',
48	    complement: '',
49	    neighborhood: '',
50	    city: '',
51	    state: '',
52	    
53	    // Operating Hours
54	    operatingHours: {
55	      monday: { isOpen: true, openTime: '09:00', closeTime: '22:00' },
56	      tuesday: { isOpen: true, openTime: '09:00', closeTime: '22:00' },
57	      wednesday: { isOpen: true, openTime: '09:00', closeTime: '22:00' },
58	      thursday: { isOpen: true, openTime: '09:00', closeTime: '22:00' },
59	      friday: { isOpen: true, openTime: '09:00', closeTime: '22:00' },
60	      saturday: { isOpen: true, openTime: '09:00', closeTime: '22:00' },
61	      sunday: { isOpen: false, openTime: '', closeTime: '' }
62	    },
63	    
64	    // Branding
65	    logo: null,
66	    primaryColor: '#2563EB'
67	  });
68	
69	  // Load saved data from localStorage on component mount
70	  useEffect(() => {
71	    const savedData = localStorage.getItem('restaurantSetupData');
72	    const savedStep = localStorage.getItem('restaurantSetupStep');
73	    const savedCompleted = localStorage.getItem('restaurantSetupCompleted');
74	    
75	    if (savedData) {
76	      setFormData(JSON.parse(savedData));
77	    }
78	    if (savedStep) {
79	      setCurrentStep(savedStep);
80	    }
81	    if (savedCompleted) {
82	      setCompletedSteps(JSON.parse(savedCompleted));
83	    }
84	
85	    getTiposEstabelecimento()
86	      .then((d) => setTiposEstabelecimento(d.tipos ?? []))
87	      .catch(() => setTiposEstabelecimento([]));
88	
89	    getPlanosDisponiveisCadastro()
90	      .then((d) => setPlanos(d.planos ?? []))
91	      .catch(() => setPlanos([]))
92	      .finally(() => setLoadingPlanos(false));
93	  }, []);
94	
95	  // Save data to localStorage whenever formData changes
96	  useEffect(() => {
97	    localStorage.setItem('restaurantSetupData', JSON.stringify(formData));
98	  }, [formData]);
99	
100	  // Save current step and completed steps
101	  useEffect(() => {
102	    localStorage.setItem('restaurantSetupStep', currentStep);
103	    localStorage.setItem('restaurantSetupCompleted', JSON.stringify(completedSteps));
104	  }, [currentStep, completedSteps]);
105	
106	  const handleInputChange = (e) => {
107	    const { name, value } = e?.target;
108	    setFormData(prev => ({
109	      ...prev,
110	      [name]: value
111	    }));
112	    
113	    // Clear error when user starts typing
114	    if (errors?.[name]) {
115	      setErrors(prev => ({
116	        ...prev,
117	        [name]: ''
118	      }));
119	    }
120	  };
121	
122	  const validateCurrentStep = () => {
123	    const newErrors = {};
124	
125	    switch (currentStep) {
126	      case 'business': {
127	        if (!formData?.establishmentTypeId) {
128	          newErrors.establishmentTypeId = 'Tipo de estabelecimento é obrigatório';
129	        }
130	        if (!formData?.restaurantName?.trim()) {
131	          newErrors.restaurantName = 'Nome do estabelecimento é obrigatório';
132	        }
133	        const tipoSelecionado = tiposEstabelecimento.find((t) => String(t.id) === String(formData?.establishmentTypeId));
134	        const isRestaurante = !tipoSelecionado || tipoSelecionado.name === 'Restaurante';
135	        if (isRestaurante && !formData?.cuisineType) {
136	          newErrors.cuisineType = 'Tipo de cozinha é obrigatório';
137	        }
138	        if (!formData?.deliveryFee || parseFloat(formData?.deliveryFee) < 0) {
139	          newErrors.deliveryFee = 'Taxa de entrega deve ser um valor válido';
140	        }
141	        if (!formData?.deliveryTime || parseInt(formData?.deliveryTime) < 10) {
142	          newErrors.deliveryTime = 'Tempo de entrega deve ser pelo menos 10 minutos';
143	        }
144	        break;
145	      }
146	
147	      case 'contact':
148	        if (!formData?.whatsapp?.trim()) {
149	          newErrors.whatsapp = 'WhatsApp é obrigatório';
150	        }
151	        if (!formData?.email?.trim()) {
152	          newErrors.email = 'Email é obrigatório';
153	        } else if (!/\S+@\S+\.\S+/?.test(formData?.email)) {
154	          newErrors.email = 'Email inválido';
155	        }
156	        if (!formData?.cep?.trim()) {
157	          newErrors.cep = 'CEP é obrigatório';
158	        }
159	        if (!formData?.address?.trim()) {
160	          newErrors.address = 'Endereço é obrigatório';
161	        }
162	        if (!formData?.number?.trim()) {
163	          newErrors.number = 'Número é obrigatório';
164	        }
165	        if (!formData?.neighborhood?.trim()) {
166	          newErrors.neighborhood = 'Bairro é obrigatório';
167	        }
168	        if (!formData?.city?.trim()) {
169	          newErrors.city = 'Cidade é obrigatória';
170	        }
171	        if (!formData?.state?.trim()) {
172	          newErrors.state = 'Estado é obrigatório';
173	        }
174	        break;
175	
176	      case 'hours':
177	        const hasOpenDay = Object.values(formData?.operatingHours || {})?.some(day => day?.isOpen);
178	        if (!hasOpenDay) {
179	          newErrors.operatingHours = 'Pelo menos um dia deve estar aberto';
180	        }
181	        break;
182	
183	      case 'branding':
184	        if (!formData?.primaryColor) {
185	          newErrors.primaryColor = 'Cor principal é obrigatória';
186	        }
187	        break;
188	    }
189	
190	    setErrors(newErrors);
191	    return Object.keys(newErrors)?.length === 0;
192	  };
193	
194	  const handleNext = () => {
195	    if (!validateCurrentStep()) return;
196	
197	    // Mark current step as completed
198	    if (!completedSteps?.includes(currentStep)) {
199	      setCompletedSteps(prev => [...prev, currentStep]);
200	    }
201	
202	    // Move to next step
203	    const steps = ['plano', 'business', 'contact', 'hours', 'branding'];
204	    const currentIndex = steps?.indexOf(currentStep);
205	    if (currentIndex < steps?.length - 1) {
206	      setCurrentStep(steps?.[currentIndex + 1]);
207	    }
208	  };
209	
210	  const handlePrevious = () => {
211	    const steps = ['plano', 'business', 'contact', 'hours', 'branding'];
212	    const currentIndex = steps?.indexOf(currentStep);
213	    if (currentIndex > 0) {
214	      setCurrentStep(steps?.[currentIndex - 1]);
215	    }
216	  };
217	
218	  const handleStepClick = (stepId) => {
219	    setCurrentStep(stepId);
220	  };
221	
222	  // Avança do passo "plano" pro "business" — chamada tanto quando não precisa
223	  // pagamento (plano com trial) quanto quando o PagamentoFaturaModal confirma
224	  // o pagamento (onPago).
225	  const avancarDePlano = () => {
226	    setFaturaPendente(null);
227	    if (!completedSteps?.includes('plano')) {
228	      setCompletedSteps((prev) => [...prev, 'plano']);
229	    }
230	    setCurrentStep('business');
231	  };
232	
233	  // Cria a loja (só com nome) + assinatura do plano escolhido e, se o plano
234	  // não tiver trial, cobra a fatura do período atual antes de liberar o
235	  // resto do formulário. Idempotente: se a loja já existe (voltou nesse
236	  // passo, ou recarregou a página), só recalcula o status de pagamento.
237	  const handleConfirmarPlano = async () => {
238	    const newErrors = {};
239	    if (!formData?.restaurantName?.trim()) newErrors.restaurantName = 'Nome do estabelecimento é obrigatório';
240	    if (!formData?.planoId) newErrors.planoId = 'Selecione um plano para continuar';
241	    if (Object.keys(newErrors).length > 0) {
242	      setErrors(newErrors);
243	      return;
244	    }
245	
246	    if (!isAuthenticated()) {
247	      navigate('/customer-registration-login', { state: { from: '/restaurant-registration-setup' } });
248	      return;
249	    }
250	
251	    setConfirmandoPlano(true);
252	    setErrors({});
253	    try {
254	      const r = await registrarRestauranteInicial({
255	        name: formData.restaurantName.trim(),
256	        plano_id: Number(formData.planoId),
257	      });
258	
259	      if (r.precisa_pagamento) {
260	        setFaturaPendente(r.fatura);
261	      } else {
262	        avancarDePlano();
263	      }
264	    } catch (error) {
265	      setErrors({ planoId: error?.message || 'Erro ao confirmar o plano. Tente novamente.' });
266	    } finally {
267	      setConfirmandoPlano(false);
268	    }
269	  };
270	
271	  const handleSaveDraft = async () => {
272	    setLoading(true);
273	    try {
274	      // Simulate API call to save draft
275	      await new Promise(resolve => setTimeout(resolve, 1000));
276	      
277	      // Show success message (you can implement a toast notification here)
278	      console.log('Rascunho salvo com sucesso!');
279	    } catch (error) {
280	      console.error('Erro ao salvar rascunho:', error);
281	    } finally {
282	      setLoading(false);
283	    }
284	  };
285	
286	  const handleCompleteSetup = async () => {
287	    if (!validateCurrentStep()) return;
288	
289	    if (!isAuthenticated()) {
290	      navigate('/customer-registration-login', { state: { from: '/restaurant-registration-setup' } });
291	      return;
292	    }
293	
294	    setLoading(true);
295	    try {
296	      if (!completedSteps?.includes(currentStep)) {
297	        setCompletedSteps(prev => [...prev, currentStep]);
298	      }
299	
300	      const address = [
301	        formData.address, formData.number, formData.neighborhood,
302	        formData.city, formData.state,
303	      ].filter(Boolean).join(', ');
304	
305	      await finalizarCadastroRestaurante({
306	        name: formData.restaurantName,
307	        address: address || undefined,
308	        state: formData.state || undefined,
309	        city: formData.city || undefined,
310	        neighborhood: formData.neighborhood || undefined,
311	        cep: formData.cep || undefined,
312	        business_hours: formData.operatingHours,
313	        type_id: formData.establishmentTypeId ? Number(formData.establishmentTypeId) : undefined,
314	      });
315	
316	      localStorage.removeItem('restaurantSetupData');
317	      localStorage.removeItem('restaurantSetupStep');
318	      localStorage.removeItem('restaurantSetupCompleted');
319	
320	      navigate('/restaurante');
321	    } catch (error) {
322	      console.error('Erro ao finalizar cadastro:', error);
323	      setErrors({ submit: error?.message || 'Erro ao finalizar cadastro. Tente novamente.' });
324	    } finally {
325	      setLoading(false);
326	    }
327	  };
328	
329	  const renderCurrentForm = () => {
330	    switch (currentStep) {
331	      case 'plano':
332	        return (
333	          <PlanSelectionForm
334	            formData={formData}
335	            onInputChange={handleInputChange}
336	            errors={errors}
337	            planos={planos}
338	            loadingPlanos={loadingPlanos}
339	            onSelectPlano={(planoId) => {
340	              setFormData((prev) => ({ ...prev, planoId }));
341	              if (errors?.planoId) setErrors((prev) => ({ ...prev, planoId: '' }));
342	            }}
343	            onConfirmar={handleConfirmarPlano}
344	            confirmando={confirmandoPlano}
345	          />
346	        );
347	      case 'business':
348	        return (
349	          <BusinessInformationForm
350	            formData={formData}
351	            onInputChange={handleInputChange}
352	            errors={errors}
353	            tiposEstabelecimento={tiposEstabelecimento}
354	          />
355	        );
356	      case 'contact':
357	        return (
358	          <ContactDetailsForm
359	            formData={formData}
360	            onInputChange={handleInputChange}
361	            errors={errors}
362	          />
363	        );
364	      case 'hours':
365	        return (
366	          <OperatingHoursForm
367	            formData={formData}
368	            onInputChange={handleInputChange}
369	            errors={errors}
370	          />
371	        );
372	      case 'branding':
373	        return (
374	          <BrandingForm
375	            formData={formData}
376	            onInputChange={handleInputChange}
377	            errors={errors}
378	          />
379	        );
380	      default:
381	        return null;
382	    }
383	  };
384	
385	  const getStepTitle = () => {
386	    switch (currentStep) {
387	      case 'plano':
388	        return 'Escolha seu Plano';
389	      case 'business':
390	        return 'Informações do Negócio';
391	      case 'contact':
392	        return 'Contato e Endereço';
393	      case 'hours':
394	        return 'Horário de Funcionamento';
395	      case 'branding':
396	        return 'Identidade Visual';
397	      default:
398	        return '';
399	    }
400	  };
401	
402	  const isLastStep = currentStep === 'branding';
403	  const isFirstStep = currentStep === 'plano';
404	
405	  return (
406	    <div className="min-h-screen bg-background">
407	      {faturaPendente && (
408	        <PagamentoFaturaModal
409	          fatura={faturaPendente}
410	          onClose={() => setFaturaPendente(null)}
411	          onPago={avancarDePlano}
412	        />
413	      )}
414	
415	      {/* Header */}
416	      <header className="bg-card border-b border-border">
417	        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
418	          <div className="flex items-center justify-between h-16">
419	            <div className="flex items-center space-x-4">
420	              <div className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center">
421	                <Icon name="Store" size={20} className="text-white" />
422	              </div>
423	              <div>
424	                <h1 className="text-lg font-semibold text-foreground">
425	                  DeliveryHub
426	                </h1>
427	                <p className="text-xs text-muted-foreground">
428	                  Configuração do Estabelecimento
429	                </p>
430	              </div>
431	            </div>
432	            
433	            <div className="flex items-center space-x-4">
434	              <Button
435	                variant="ghost"
436	                onClick={() => navigate('/customer-registration-login')}
437	                iconName="ArrowLeft"
438	                iconPosition="left"
439	              >
440	                Voltar
441	              </Button>
442	            </div>
443	          </div>
444	        </div>
445	      </header>
446	      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
447	        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
448	          {/* Progress Sidebar - Desktop */}
449	          <div className="hidden lg:block">
450	            <ProgressSidebar
451	              currentStep={currentStep}
452	              onStepClick={handleStepClick}
453	              completedSteps={completedSteps}
454	            />
455	          </div>
456	
457	          {/* Main Content */}
458	          <div className="lg:col-span-3">
459	            <div className="bg-card rounded-lg border border-border">
460	              {/* Mobile Progress Header */}
461	              <div className="lg:hidden border-b border-border p-6">
462	                <div className="flex items-center justify-between mb-4">
463	                  <h2 className="text-xl font-semibold text-foreground">
464	                    {getStepTitle()}
465	                  </h2>
466	                  <span className="text-sm text-muted-foreground">
467	                    {completedSteps?.length + 1}/5
468	                  </span>
469	                </div>
470	                <div className="w-full bg-muted rounded-full h-2">
471	                  <div
472	                    className="bg-primary h-2 rounded-full transition-all duration-300"
473	                    style={{
474	                      width: `${((completedSteps?.length + 1) / 5) * 100}%`
475	                    }}
476	                  ></div>
477	                </div>
478	              </div>
479	
480	              {/* Form Content */}
481	              <div className="p-6 lg:p-8">
482	                {/* Desktop Header */}
483	                <div className="hidden lg:block mb-8">
484	                  <h2 className="text-2xl font-semibold text-foreground mb-2">
485	                    {getStepTitle()}
486	                  </h2>
487	                  <p className="text-muted-foreground">
488	                    Preencha as informações abaixo para configurar seu estabelecimento
489	                  </p>
490	                </div>
491	
492	                {/* Form */}
493	                <div className="max-w-2xl">
494	                  {renderCurrentForm()}
495	                </div>
496	
